# Function to calculate factorial
# Input: n (non-negative integer)
calculate_factorial <- function(n) {
  if (n == 0 || n == 1) {
    return(1)
  } else {
    return(n * calculate_factorial(n - 1))
  }
}
print(calculate_factorial(5))

