# Example: read numbers until a negative value is entered
repeat {
  num <- as.numeric(readline(prompt = "Enter a number (negative to stop): "))
  if (is.na(num)) {
    cat("Invalid input, try again\n")
    next
  }
  if (num < 0) {
    cat("Stopping loop.\n")
    break
  }
  cat("You entered:", num, "\n")
}

