# Define a user-defined function to calculate standard error
calc_se <- function(x) {
  n <- length(x)
  sd_val <- sd(x)
  se <- sd_val / sqrt(n) # Calculate standard error
  return(se)
}

sample_data <- c(10, 12, 23, 14, 15)
print(calc_se(sample_data))

