factorial_func <- function(n) {
  if (n <= 1) return(1)
  return(n * factorial_func(n - 1))
}

is_prime <- function(n) {
  if (n <= 1) return(FALSE)
  for (i in 2:sqrt(n)) {
    if (n %% i == 0) return(FALSE)
  }
  return(TRUE)
}

