# Function demonstrating positional, named, and default arguments
calculate_power <- function(base, exponent = 2, print_msg = TRUE) {
  res <- base ^ exponent
  if (print_msg) {
    cat('Result of', base, '^', exponent, 'is:', res, '\n')
  }
  return(res)
}

# 1. Positional call
calculate_power(3, 3)

# 2. Named call out of order
calculate_power(print_msg = FALSE, exponent = 4, base = 2)

# 3. Using default argument for exponent
calculate_power(5)

